// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool firstOk;
        vm.prank(caller);
        try c.Initialized{gas: gasleft()}() {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        bool secondOk;
        vm.prank(caller);
        try c.Initialized{gas: gasleft()}() {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        assertTrue(firstOk && secondOk);
    }
}
